// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(0));
        // make actor the current owner so the call is admissible (does not revert)
        vm.prank(address(this));
        c.setOwner(actor);
        vm.prank(actor);
        bool ok = c.setOwner(newOwner);
        // General rule: any completing setOwner call by the current owner returns true.
        assertTrue(ok);
    }
}
